// План specs/estimates.md 1.1 / 1.2 (#ca1a27). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Ничего не сохраняет (@prod-safe).
// Открытый реджект 17.11: Save/Send без клиента и позиций не должны открывать системное окно (alert) — сообщение у каждого пустого поля
// внутри страницы. Комментарий программиста: клиент — красная рамка у «Select Client» + «Please select a client»; позиции — красная рамка + «Please add at least one item».
// Факты 17.11: ошибки у полей без alert, EST в /assessments, 375 ок. Без пометки устройства — десктоп + телефоны (375).
import { test, expect } from '../../fixtures';
import { ROLE, pp } from '../pricebook/pricebook-helpers';
import { NO_CLIENT, NO_ITEMS, openEmptyNewEstimate, watchAssessmentWrites, watchDialogs } from './estimates-helpers';

test.describe('New Estimate — validation messages at the fields (#ca1a27)', () => {
  test('Save with no client and no items: messages at both fields, no system dialog, nothing saved #ca1a27 @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    const dialogs = watchDialogs(page);
    await openEmptyNewEstimate(page);
    const writes = watchAssessmentWrites(page);

    await page.getByRole('button', { name: 'Save', exact: true }).filter({ visible: true }).first().click();
    await expect(page.getByText(NO_CLIENT).first()).toBeVisible();
    await expect(page.getByText(NO_ITEMS).first()).toBeVisible();
    expect(dialogs, 'системного окна (alert) быть не должно').toEqual([]);
    expect(writes, 'смета не сохраняется без клиента и позиций').toEqual([]);
    await expect(page, 'остались на форме').toHaveURL(/\/EstimateCreation/);
  });

  test('Send with no client and no items: same messages, no system dialog, no Send window #ca1a27 @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    const dialogs = watchDialogs(page);
    await openEmptyNewEstimate(page);
    const writes = watchAssessmentWrites(page);

    await page.getByRole('button', { name: 'Send', exact: true }).filter({ visible: true }).last().click();
    await expect(page.getByText(NO_CLIENT).first()).toBeVisible();
    await expect(page.getByText(NO_ITEMS).first()).toBeVisible();
    await expect(page.getByRole('dialog', { name: 'Send Estimate' })).toHaveCount(0);
    expect(dialogs, 'системного окна (alert) быть не должно').toEqual([]);
    expect(writes).toEqual([]);
  });

  test('Direct /assessments lists estimates created from the app (page opens, Total Estimates shown) #ca1a27 @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await page.addInitScript(() => { try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ } });
    await page.goto(pp('/assessments'));
    await expect(page.getByText('Total Estimates', { exact: true })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(/EST-\d{4}/).first()).toBeVisible();
  });
});
